1|import SwiftUI
2|import Combine
3|
4|class TabSelection: ObservableObject {
5|    @Published var selectedTab: Int = 0
6|}
7|
8|struct MainTabView: View {
9|    @EnvironmentObject var appState: AppState
10|    @StateObject private var tabSelection = TabSelection()
11|    
12|    var body: some View {
13|        TabView(selection: $tabSelection.selectedTab) {
14|            HomeView()
15|                .environmentObject(appState.favoritesManager)
16|                .tabItem {
17|                    Label("Home", systemImage: tabSelection.selectedTab == 0 ? "house.fill" : "house")
18|                }
19|                .tag(0)
20|                .accessibilityIdentifier("tab_home")
21|            
22|            // BUG: Notes tab omitted — users cannot reach Notes
23|            FavoritesView()
24|                .environmentObject(appState.favoritesManager)
25|                .tabItem {
26|                    Label("Favorites", systemImage: tabSelection.selectedTab == 2 ? "heart.fill" : "heart")
27|                }
28|                .tag(2)
29|                .accessibilityIdentifier("tab_favorites")
30|            
31|            MenuView()
32|                .tabItem {
33|                    Label("Menu", systemImage: tabSelection.selectedTab == 3 ? "line.3.horizontal" : "line.3.horizontal")
34|                }
35|                .tag(3)
36|                .accessibilityIdentifier("tab_menu")
37|            
38|            CartView()
39|                .tabItem {
40|                    Label("Cart", systemImage: tabSelection.selectedTab == 4 ? "cart.fill" : "cart")
41|                }
42|                .tag(4)
43|                .accessibilityIdentifier("tab_cart")
44|        }
45|        .accentColor(.purple)
46|        .onAppear {
47|            let appearance = UITabBarAppearance()
48|            appearance.configureWithOpaqueBackground()
49|            appearance.backgroundColor = UIColor.systemBackground
50|            appearance.shadowColor = UIColor.black.withAlphaComponent(0.1)
51|            
52|            UITabBar.appearance().standardAppearance = appearance
53|            UITabBar.appearance().scrollEdgeAppearance = appearance
54|        }
55|    }
